sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    var courseId = g_form.getValue('course');  // Obtém o ID do curso
    var scheduleDate = newValue;  // Obtém a nova data selecionada

    var ga = new GlideAjax('ScheduleUtils');  // Nome do Script Include
    ga.addParam('sysparm_name', 'checkScheduleConflict');  // Função a ser chamada no Script Include
    ga.addParam('sysparm_course_id', courseId);  
    ga.addParam('sysparm_schedule_date', scheduleDate);  

    ga.getXMLAnswer(function(response) {
        var result = response;  

        if (result == 'false') {
            g_form.addErrorMessage( 'Já existe um schedule para este curso nesta data.', 'error');
			g_form.clearMessages();

        }
    });
}
